function id(){return "tpl_"+Math.random().toString(36).slice(2,10)}
function build(template,geo){
 const [category,name,description,side,role,outcome,horizon,varNames]=template;
 const variables=varNames.split(";").map((n,i)=>({id:id(),name:n.replace(/\b\w/g,c=>c.toUpperCase()),description:"Starter hypothesis for "+n+". Replace with locally observed or sourced evidence.",level:5,low:2,high:8,importance:i<4?8:6,direction:["risk","cost","friction","competition","churn","delay","barrier"].some(k=>n.includes(k))?"negative":"mixed",confidence:"low",evidenceStatus:"assumption",source:"",notes:"Illustrative template assumption; validate for this specific case."}));
 const actors=[
 {name:"Primary decision-maker",type:"person",role,goals:outcome,incentives:"Personal or organizational benefit; clarify from evidence.",resources:"Time, authority and access to be assessed.",constraints:"Capacity, competing priorities and external rules.",information:"Partial and potentially asymmetric information.",beliefs:"Unknown until observed.",behaviour:"May cooperate, delay, negotiate, resist or adapt.",policy:"custom",power:6,confidence:"low"},
 {name:"Counterparty / affected participant",type:"person",role:"Customer, counterpart or affected stakeholder",goals:"Their own preferred outcome, not necessarily aligned with the model owner.",incentives:"Benefits, costs, risks and alternatives require investigation.",resources:"Unknown; map before assigning leverage.",constraints:"Budget, authority, timing and access may apply.",information:"May see different information.",behaviour:"May accept, reject, defer, negotiate or choose alternatives.",policy:"negotiate",power:5,confidence:"low"},
 {name:"Gatekeeper / institution",type:"institution",role:"Approver, platform, regulator or procedural gate",goals:"Apply its mandate, rules or platform procedures.",incentives:"Compliance, performance, risk control and institutional priorities.",resources:"Formal authority and process access.",constraints:"Jurisdiction, policy, capacity and discretion.",information:"Access may be limited to submitted evidence.",behaviour:"May approve, request evidence, delay or reject.",policy:"delay",power:6,confidence:"low"},
 {name:"Alternative / competitor",type:"company",role:"Substitute, competitor or outside option",goals:"Attract the same resources, attention or transaction.",incentives:"Own objectives and strategic position.",resources:"Unknown; research required.",constraints:"Capacity, cost and market position.",information:"May react to visible actions.",behaviour:"May differentiate, match, ignore or counter.",policy:"compete",power:5,confidence:"low"}
 ].slice(0,side==="person"?3:4).map(a=>({...a,id:id(),priority:6,goalAlignment:0,incentivePressure:5,resourceCapacity:5,perceivedRisk:5,informationConfidence:3,riskTolerance:5,timePressure:5,learningRate:.25}));
 const links=[]; for(let i=0;i<Math.min(variables.length-1,12);i++) links.push({id:id(),from:variables[i].id,to:variables[i+1].id,sign:"positive",strength:1,delay:1,reason:"Possible mechanism to investigate; confirm direction and timing."});
 const decisions=[{id:id(),name:"Small reversible validation test",description:"Run a low-cost test before committing major resources.",actorId:actors[0].id,mechanism:"Generate observable evidence about demand, access, trust or feasibility.",cost:"Low / bounded",time:"Short",reversibility:"high",downside:"Small test may not represent the full market or population.",response:"Participants may ignore, misunderstand or respond differently under real stakes.",effectText:""}];
 const institutions=[{id:id(),name:"Formal rules and approval process",type:"procedure",scope:"Jurisdiction and organization must be specified",when:1,severity:5,enforcement:5,responseEffect:"delay",notes:"Placeholder only. Research applicable rules and cite source/date; do not assume a country."},{id:id(),name:"Informal norms and access conditions",type:"informal norm",scope:"Specific subgroup, setting and situation",when:1,severity:4,enforcement:3,responseEffect:"mixed",notes:"Do not generalize culture. Record observed variation, exceptions and evidence."}];
 const events=[{id:id(),name:"Initial response / first feedback",description:"Observe the first meaningful response and record who responded, what they did and under what conditions.",when:1,kind:"conditional",likelihood:"unknown",status:"possible",actorId:actors[1]?.id||"",effects:{}}];
 const resources=[{id:id(),name:"Time and operating capacity",initial:5,capacity:10,consumptionPerStep:1,replenishmentPerStep:0,notes:"Illustrative units; define what one unit means."}];
 const constraints=[{id:id(),name:"Budget / capacity / access limit",type:"soft",severity:5,when:1,until:"",notes:"Replace with measured or sourced constraint."}];
 const evidence=[{id:id(),name:"Baseline observation",description:"Record current state, sample, date, source and measurement method.",status:"unknown",source:"",date:"",confidence:"low"}];
 return {meta:{title:name+" — STRATOS template",domainPack:category,modelStatus:"draft",templateId:name},situation:{description,outcome,position:"To be completed from current observations.",deadline:"",timeHorizon:horizon,boundary:"Include only actors, mechanisms and geography relevant to this decision. State exclusions explicitly.",country:geo.country||"",region:geo.region||"",locality:geo.locality||"",geography:[geo.country,geo.region,geo.locality].filter(Boolean).join(", "),industry:category,market:"Define target segment, alternatives and channel; not pre-assumed.",institution:"",legal:"Research applicable law and regulation for the selected jurisdiction. No legal claims are pre-filled.",social:"Record observed norms with subgroup, setting, source and date. No national or cultural behaviour is assumed."},actors,variables,links,events,communications:[],relationships:[],powerRelations:[],institutions,markets:[{id:id(),name:"Primary market / environment",segment:"To define",demand:"Unknown",priceSensitivity:"Unknown",awareness:"Unknown",notes:"Specify geography, segment, source and market period."}],segments:[{id:id(),name:"Primary segment",needs:"To validate",purchasingPower:"Unknown",accessibility:"Unknown",notes:"Avoid treating a broad population as homogeneous."}],competitors:[{id:id(),name:"Main alternative / substitute",pricing:"Unknown",differentiation:"Unknown",capacity:"Unknown",reputation:"Unknown",notes:"Research actual alternatives."}],journeys:[{id:id(),name:"Participant journey",stages:"Discovery; interest; evaluation; trust; access; contact; approval; payment; delivery; retention",notes:"Remove irrelevant stages and add context-specific steps."}],journeyPoints:[],negotiations:[{id:id(),name:"Potential agreement / decision",buyerCeiling:"",sellerFloor:"",status:"unverified",notes:"Only populate reservation values when known."}],negotiationParties:actors.slice(0,2).map(a=>({id:id(),name:a.name,role:"party",willingness:"unknown",authority:"unknown",walkAway:"unknown"})),decisionInteractions:[],reputationEvents:[],groups:[{id:id(),name:"Relevant stakeholder group",memberIds:actors.map(a=>a.id).join(","),supportLevel:50,decisionThreshold:50,cohesion:5,coordination:5,conformityPressure:3,effects:"To be defined from observed collective behaviour."}],groupEvents:[],aiSystems:[{id:id(),name:"Potential AI or automated system — confirm whether present",systemType:"AI assistant / agent / recommender / automated workflow / other / none",role:"monitor",when:1,adoption:0,reliability:5,oversight:5,targetActors:actors.map(a=>a.id).join(","),variableEffects:"No model effect until a real system, task and exposure are confirmed.",bias:"Unknown. Check performance across relevant tasks and affected groups; do not assume bias is present or absent.",failureMode:"Possible incorrect output, outage, bias, privacy or security incident, automation error, or over-reliance. Confirm which risks apply.",operator:"To identify",dataInputs:"To identify; record source, permission, quality and sensitivity.",humanOverride:"Confirm who can review, reject, correct or stop the system.",limitations:"Capabilities and limits are unknown until the actual tool and use case are identified.",notes:"Optional AI coverage prompt. Adoption is set to zero because AI involvement has not been established. Delete if irrelevant; edit when evidence is available.",status:"unconfirmed"}],aiEvents:[{id:id(),name:"Check for AI or automated influence",eventType:"assessment",when:1,intensity:0,systemAId:"",systemBId:"",successEffects:"No effect assumed. If AI is present, describe the verified benefit and measure it.",failureEffects:"No failure assumed. Record only observed or credible failure modes.",governance:"Identify operator, accountability, permissions, review, audit and escalation arrangements if applicable.",humanImpact:"Check effects on workload, access, decisions, affected people and human control. Mark unknowns.",status:"unconfirmed"}],relationships:[],powerRelations:[],constraints,resources,dependencies:[],decisions,branches:[],scenarioOverrides:{base:{},favourable:{},adverse:{},custom:{}},experiments:[{id:id(),name:"One-variable feedback experiment",hypothesis:"Changing one controllable factor will produce an observable signal.",measure:"Define a metric, baseline, sample and decision threshold.",cost:"Low",speed:"Fast signal",status:"open"}],evidence,runs:[]};
}


function applyContextProfile(model,pack){
 const name=pack[1],category=pack[0],role=pack[4],goal=pack[5];
 const profiles=[
  [/music|creative|podcast|film|gaming|publishing|event|sports|sponsorship/i,{actors:["Creator / rights holder","Artist, client or commissioning buyer","Platform, label or decision-maker","Competing catalogue or alternative"],market:"Audience, commissioning market or distribution channel",segment:"Intended audience / buyer segment",competitor:"Alternative creator, catalogue or substitute",journey:"Brief / discovery; fit review; rights check; pitch; approval; terms; delivery; payment; reporting",negotiation:"Creative brief, licence or placement agreement",evidence:"Rights, ownership, metadata, audience and placement evidence",ai:"AI used for discovery, recommendation, content production, rights matching or analytics — verify whether present."}],
  [/broker|intermediat|real estate|insurance|mortgage|freight|talent|procurement|sourcing/i,{actors:["Broker / intermediary","Client / principal","Supplier, buyer or approving party","Alternative intermediary or competing offer"],market:"Transaction market and available counterparties",segment:"Client / counterparty segment",competitor:"Alternative broker, direct route or substitute",journey:"Mandate; qualification; verification; matching; introduction; due diligence; negotiation; closing; fee settlement",negotiation:"Mandate, commission and transaction terms",evidence:"Authority, legitimacy, eligibility, fees and transaction verification",ai:"AI used for matching, valuation, screening, document processing or lead scoring — verify."}],
  [/negotiation|conflict|dispute|salary|compensation|contract|vendor|debt|partnership/i,{actors:["Person leading the negotiation","Counterparty","Approver, adviser or mediator","Alternative party or outside option"],market:"Agreement environment and available alternatives",segment:"Parties and interests",competitor:"Outside option or competing proposal",journey:"Preparation; opening; information exchange; proposal; counterproposal; approval; agreement; implementation",negotiation:"Main agreement and terms under discussion",evidence:"Authority, stated interests, limits, alternatives and commitments",ai:"AI used for drafting, research, negotiation support or automated decisions — verify."}],
  [/student|university|campus|school|scholarship|academic|course|education/i,{actors:["Student, applicant or learner","Peer, teacher or other participant","Institution, administrator or decision-maker","Alternative applicant or competing option"],market:"Education or opportunity environment",segment:"Student / applicant / learner group",competitor:"Alternative course, applicant or opportunity",journey:"Awareness; eligibility; application; evidence; review; decision; enrolment; participation; outcome",negotiation:"Request, appeal or institutional decision",evidence:"Eligibility, deadlines, documents, performance and official requirements",ai:"AI used for admissions, grading, tutoring, recommendations or student support — verify."}],
  [/dating|relationship|friendship|family|household|social network|community/i,{actors:["You / person initiating the interaction","Other person or people involved","Relevant group or shared environment","Outside influence or alternative"],market:"Social setting and opportunities for interaction",segment:"People directly involved; avoid generalising others",competitor:"Competing priorities, relationships or social options",journey:"Initial contact; interaction; response; trust; mutual understanding; boundary or commitment; follow-through",negotiation:"Shared expectation, boundary or unresolved issue",evidence:"Observed words, actions, consistency and stated boundaries",ai:"AI used for recommendations, moderation, messaging or ranking — verify."}],
  [/healthcare|patient|clinic|public health/i,{actors:["Patient or service user","Care provider / frontline worker","Clinic, administrator or responsible authority","Alternative service or referral option"],market:"Care service and access environment",segment:"Patient or service-user group",competitor:"Alternative provider or care pathway",journey:"Need; information; eligibility; referral; appointment; assessment; care; follow-up",negotiation:"Care plan, access decision or service arrangement",evidence:"Clinical or service records, eligibility, capacity and verified guidance",ai:"AI used for triage, diagnostics, records or scheduling — verify; human clinical oversight is essential."}],
  [/cyber|outage|emergency|incident|fraud|scam|safety|business continuity/i,{actors:["Incident owner / response lead","Affected people or customers","Response authority / service provider","Threat source, dependency or external responder"],market:"Operational environment and affected services",segment:"Affected users, systems or locations",competitor:"Alternative service, threat actor or substitute route",journey:"Detection; verification; containment; communication; recovery; review; prevention",negotiation:"Response coordination, access or recovery decision",evidence:"Incident timeline, logs, reports, impact and verified source material",ai:"AI used for detection, triage, response or monitoring — verify; test false positives and escalation."}],
  [/business|startup|sales|customer|product|retail|manufactur|agency|restaurant|cash flow|franchise|subscription|ecommerce/i,{actors:["Owner / operator / decision-maker","Customer, buyer or user","Supplier, partner or approving party","Competitor or substitute"],market:"Customer market and operating environment",segment:"Primary customer / user segment",competitor:"Main competitor or substitute",journey:"Discovery; interest; evaluation; trust; access; purchase; delivery; use; retention; referral",negotiation:"Customer, supplier or commercial agreement",evidence:"Demand, willingness to pay, costs, delivery and customer behaviour",ai:"AI used for marketing, sales, support, operations or recommendations — verify."}]
 ];
 const profile=profiles.find(x=>x[0].test(name))?.[1]||{
  actors:[role,"Other affected participant","Relevant organization or decision-maker","Alternative or outside influence"],
  market:"Relevant operating environment and exchange",segment:"People or organizations directly affected",competitor:"Alternative route, competing interest or substitute",
  journey:"Awareness; access; first interaction; decision; action; follow-through; outcome",
  negotiation:"Relevant agreement, request or decision",evidence:"Observed behaviour, documents, dates, sources and measurable results",
  ai:"AI or automated tools that may influence access, decisions, communication or outcomes — verify whether present."
 };
 model.actors.forEach((a,i)=>{
  a.name=profile.actors[i]||a.name;
  a.role=[role,"Directly involved participant","Decision-maker, platform or institution","Alternative, competitor or outside option"][i]||a.role;
  a.goals=i===0?goal:(i===1?"Their own needs, incentives and preferred outcome must be established.":"Clarify the actual mandate, interests and decision rights.");
  a.notes=(a.notes||"")+" Context-specific role generated for "+name+". Confirm the real person or organization and replace assumptions with observed evidence.";
 });
 if(model.markets?.[0]){model.markets[0].name=profile.market;model.markets[0].notes="Define geography, participants, current conditions, evidence date and relevant alternatives. This is a prompt, not a factual market claim.";}
 if(model.segments?.[0]){model.segments[0].name=profile.segment;model.segments[0].notes="Describe the specific subgroup, needs, access, constraints and evidence. Do not assume a population is homogeneous.";}
 if(model.competitors?.[0]){model.competitors[0].name=profile.competitor;model.competitors[0].notes="Identify real alternatives and compare on evidence; do not assume a named competitor exists.";}
 if(model.journeys?.[0]){model.journeys[0].name=profile.journey.split(";")[0]+" to outcome";model.journeys[0].stages=profile.journey;model.journeys[0].notes="Stages are editable. Remove irrelevant steps and add local process steps, delays, barriers and evidence.";}
 if(model.negotiations?.[0]){model.negotiations[0].name=profile.negotiation;model.negotiations[0].notes="Only enter limits, authority or commitments when verified. Blank values mean unknown, not zero.";}
 if(model.evidence?.[0]){model.evidence[0].name="Baseline: "+profile.evidence;model.evidence[0].description="Capture the current state, source, date, sample, method, uncertainty and what would change the decision.";}
 if(model.aiSystems?.[0]){Object.assign(model.aiSystems[0],{name:"AI / automation check for "+name,role:"monitor",notes:profile.ai+" No AI use is assumed. Confirm presence, operator, users, task, data, reliability, oversight and measured effects; delete if irrelevant."});}
 if(model.aiEvents?.[0]){model.aiEvents[0].name="Check AI influence on "+name;model.aiEvents[0].humanImpact="Identify who may be affected, what decisions may be influenced, whether people can appeal or override, and what remains unknown. "+profile.ai;}
 if(model.decisions?.[0]){model.decisions[0].name="First low-cost test for "+name;model.decisions[0].description="Choose one reversible action that tests the most important uncertainty before committing major resources.";}
 if(model.experiments?.[0]){model.experiments[0].name="Test the main uncertainty in "+name;model.experiments[0].hypothesis="A small real-world test will reveal whether the most important assumption holds.";model.experiments[0].measure="Record a baseline, sample, action, response, time to feedback and a clear continue/change/stop threshold.";}
 if(model.resources?.[0])model.resources[0].name="Main resources: time, money, people and access";
 if(model.constraints?.[0])model.constraints[0].name="Main limits: rules, capacity, budget, time and access";
 model.situation.aiExtraContext="AI review for this context: "+profile.ai+" AI involvement is unconfirmed; do not invent AI adoption or impact.";
}

const stages=[["Early discovery","Test whether the need, problem or opportunity exists before committing heavily."],["Initial launch","Coordinate first access, first users or first transaction and collect early signals."],["Growth and scaling","Expand reach or capacity while protecting quality, trust and unit economics."],["Established operation","Improve reliability, efficiency, retention, governance or defensibility."],["Decline or disruption","Respond to weakening performance, substitution, shocks or loss of relevance."]];
const stakeholderModes=[["Solo decision-maker","One primary actor makes the decision but depends on external responses."],["Buyer and seller","A bilateral exchange with different interests, information and walk-away options."],["Multi-party coalition","Several parties have different incentives, vetoes and coordination costs."],["Group and network","Peer influence, norms, reputation and collective action shape choices."],["Institution and gatekeepers","Formal procedures, approvers, platform rules or regulators shape access."]];
const environments=[["Physical / local","In-person access, location, operating hours, travel and local infrastructure matter."],["Digital / platform-mediated","Discovery, ranking, platform rules, data and digital trust shape the interaction."],["Hybrid / omnichannel","Participants move between physical and digital touchpoints; handoffs can fail."],["Regulated / institution-led","Eligibility, formal approval, documentation, oversight and jurisdiction matter."],["Cross-border / distributed","Language, time zones, currencies, logistics and local institutional differences matter."]];
const pressures=[["Resource-constrained","Limited budget, staff, time or infrastructure make prioritisation important."],["Time-critical","A deadline or short opportunity window affects choices."],["High uncertainty","Evidence is incomplete, noisy or contested; assumptions need tests."],["Competitive / contested","Alternatives, rivals or opposing stakeholders can react strategically."]];
const combinations=[];for(let s=0;s<stages.length;s++)for(let m=0;m<stakeholderModes.length;m++)for(let e=0;e<environments.length;e++)for(let q=0;q<pressures.length;q++)combinations.push({stage:stages[s],stakeholders:stakeholderModes[m],environment:environments[e],pressure:pressures[q]});
